// Medical Terminology Practice Test 4. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and using different terms from Practice Tests 1–3.
import {q, mix} from './q.js';
const EHR='Ehrlich, Medical Terminology for Health Professions', STAN='Stanhope & Turnbull, Introduction to Medical Terminology', TAB='Taber’s Cyclopedic Medical Dictionary';
const WP='Roots, Prefixes, Suffixes, and Combining Forms', BODY='Overview of Body', SKEL='Skeletal', MUS='Muscular', RESP='Respiratory', DIG='Digestive', CV='Cardiovascular & Lymphatic', NERV='Nervous/Special Senses', ENDO='Endocrine', REPRO='Reproductive', INTEG='Integumentary', URIN='Urinary';

export default {
 id:'medical-terminology-4',
 event:'Medical Terminology',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Ehrlich’s Medical Terminology for Health Professions, Stanhope & Turnbull, and Taber’s Cyclopedic Medical Dictionary',
 plan:[{area:WP,weight:45},{area:BODY,weight:5},{area:SKEL,weight:5},{area:MUS,weight:5},{area:RESP,weight:5},{area:DIG,weight:5},{area:CV,weight:5},{area:NERV,weight:5},{area:ENDO,weight:5},{area:REPRO,weight:5},{area:INTEG,weight:5},{area:URIN,weight:5}],
 questions:mix([
  q(WP,'What does the suffix -rrhea mean?','Flow or discharge',['Rupture or tear','Bleeding or bursting','Suture or repair'],'A','Diarrhea and rhinorrhea describe flow. Rupture is -rrhexis, bursting forth of blood is -rrhage and suturing is -rrhaphy.',EHR),
  q(WP,'In the term hemostasis, what does -stasis mean?','Stopping or controlling',['Flowing or moving','Forming or making','Breaking apart'],'B','Hemostasis is the stopping of bleeding; -poiesis means formation and -lysis means breaking apart.',EHR),
  q(WP,'What does the suffix -osis usually mean?','Abnormal condition',['Inflammation','Surgical removal','Instrument'],'C','Cyanosis and necrosis name abnormal conditions. Inflammation is -itis, removal is -ectomy and instrument is -scope or -meter.',EHR),
  q(WP,'Which suffix means “pertaining to”?','-ac',['-cyte','-oma','-ist'],'D','-ac, -al, -ar, -ic and -ous all mean pertaining to, as in cardiac. -cyte means cell, -oma tumor and -ist specialist.',EHR),
  q(WP,'Which suffix, like -algia, means “pain”?','-dynia',['-desis','-tripsy','-plasia'],'A','Gastrodynia and gastralgia both mean stomach pain. -desis means binding, -tripsy crushing and -plasia formation.',EHR),
  q(WP,'What does the suffix -iatry mean?','Medical treatment',['Study of disease','Fear of an object','Measurement'],'B','Psychiatry is treatment of the mind. Study is -logy, fear is -phobia and measurement is -metry.',EHR),
  q(WP,'What does the suffix -cyte mean?','Cell',['Tissue','Sac','Fluid'],'C','Leukocytes are white cells and thrombocytes are platelets. A sac or bladder is cyst/o.',EHR),
  q(WP,'What does the suffix -genic mean?','Producing or caused by',['Weakness or lack of','Treatment of','Study of the body'],'D','Carcinogenic means cancer-producing and pathogenic means disease-producing.',EHR),
  q(WP,'What does the prefix eu- mean?','Good or normal',['Bad or difficult','Without or absent','Above or excessive'],'A','Eupnea is normal breathing. Dys- means bad or difficult, a- means without and hyper- means above.',EHR),
  q(WP,'What does the prefix ecto- mean?','Outside',['Within','Above','Between'],'B','An ectopic pregnancy develops outside the uterus. Endo- means within, supra- above and inter- between.',EHR),
  q(WP,'What does the prefix supra- mean?','Above',['Below','Behind','Beside'],'C','Suprapubic means above the pubic bone. Below is infra- or sub-, behind is retro- and beside is para-.',EHR),
  q(WP,'What does the prefix retro- mean?','Behind or backward',['Before or in front','Again or back','Across or through'],'D','Retroperitoneal means behind the peritoneum. Before is pre- or ante-, again is re- and across is trans-.',EHR),
  q(WP,'What does the prefix trans- mean?','Across or through',['Under or beneath','Within or inside','Near or beside'],'A','Transdermal means through the skin, as with a medication patch.',EHR),
  q(WP,'In the term diarrhea, what does the prefix dia- mean?','Through or complete',['Twice or double','Painful or difficult','Apart or away from'],'B','Dia- means through, as in diarrhea (flow through) and dialysis (separation through a membrane). Di- means two.',EHR),
  q(WP,'What does the combining form spondyl/o refer to?','Vertebra',['Spinal cord','Sternum','Shoulder'],'C','Spondylosis is degeneration of the vertebrae; vertebr/o also means vertebra, while myel/o refers to the spinal cord.',EHR),
  q(WP,'What does the combining form pyr/o mean?','Fever or fire',['Pus','Kidney pelvis','Stomach opening'],'D','Antipyretics reduce fever. Pus is py/o, renal pelvis is pyel/o and the stomach’s exit is pylor/o.',EHR),
  q(WP,'What does the combining form thromb/o mean?','Clot',['Thorax','Thymus','Thyroid'],'A','A thrombus is a stationary clot; thorac/o is chest, thym/o is the thymus and thyr/o is the thyroid.',EHR),
  q(WP,'What does the combining form trich/o refer to?','Hair',['Nail','Sweat','Oil'],'B','Trichomycosis is a fungal hair condition. Nail is onych/o, sweat is hidr/o and oil is seb/o.',EHR),
  q(WP,'The combining form kerat/o can refer to which two structures?','Hard, horny tissue and the cornea',['The kidney and the bladder','The cheek and the lip','The tear duct and the eyelid'],'C','Keratosis is a horny skin growth, and keratitis is inflammation of the cornea.',EHR),
  q(WP,'What does the combining form sial/o refer to?','Saliva',['Sinus','Side','Skin'],'D','Sialadenitis is inflammation of a salivary gland. Sinus is sinus/o, and skin is derm/o or cutane/o.',EHR),
  q(WP,'What does the combining form ankyl/o mean?','Crooked, bent or stiff',['Ankle or heel','Vessel or duct','Straight or upright'],'A','Ankylosing spondylitis causes stiffening of the spine. Ankle is tars/o, vessel is angi/o and straight is orth/o.',EHR),
  q(WP,'What is the plural of bronchus?','Bronchi',['Bronchuses','Bronchae','Bronchia'],'B','Words ending in -us usually form plurals by changing -us to -i, as in bronchus/bronchi and alveolus/alveoli.',EHR),
  q(WP,'Which suffix means “specialist”?','-ologist',['-ology','-iasis','-ectasis'],'C','A cardiologist is a heart specialist; -ology is the study, -iasis is a condition and -ectasis is dilation.',EHR),
  q(BODY,'Which plane divides the body into upper and lower portions?','Transverse plane',['Sagittal plane','Frontal plane','Coronal plane'],'D','The transverse (horizontal) plane separates superior and inferior parts; sagittal divides left and right.',EHR),
  q(BODY,'The ears are ______ to the nose.','Lateral',['Medial','Proximal','Anterior'],'A','Lateral means farther from the midline; medial means closer to it. The nose lies on the midline.',EHR),
  q(BODY,'Which term describes the back of the body?','Dorsal',['Ventral','Caudal','Superficial'],'B','Dorsal or posterior refers to the back; ventral or anterior refers to the front. Caudal means toward the tail.',EHR),
  q(SKEL,'What is osteomyelitis?','Infection of bone and marrow',['Softening of bone tissue','Tumor of the bone marrow','Loss of bone density'],'C','Oste/o (bone) + myel/o (marrow) + -itis. It is usually bacterial and may follow injury or surgery.',EHR),
  q(SKEL,'Which term means surgical repair or replacement of a joint?','Arthroplasty',['Arthroscopy','Arthrodesis','Arthrotomy'],'D','Arthroplasty includes joint replacement. Arthroscopy is visual examination, arthrodesis is fusion and arthrotomy is incision.',EHR),
  q(MUS,'What is tendinitis?','Tendon inflammation',['A torn ligament','Muscle spasm','A bruised bone'],'A','Tendin/o or ten/o (tendon) + -itis. Tendons connect muscle to bone; ligaments connect bone to bone.',EHR),
  q(MUS,'Which term describes bending the foot upward toward the shin?','Dorsiflexion',['Plantar flexion','Eversion','Inversion'],'B','Dorsiflexion raises the toes; plantar flexion points them down, as when standing on tiptoe.',EHR),
  q(RESP,'What is orthopnea?','Breathlessness lying flat',['Breathing very rapidly','Breathing with a whistle','Stopping breathing in sleep'],'C','Orth/o (straight, upright) + -pnea. Patients with heart failure often need pillows to breathe while lying down.',EHR),
  q(RESP,'What is a tracheostomy?','An opening into the trachea',['Removal of the entire trachea','Repair of the trachea','Viewing of the trachea'],'D','-stomy means creating an opening; the stoma allows breathing through the neck.',EHR),
  q(DIG,'What does dyspepsia mean?','Indigestion',['Vomiting blood','Constipation','Difficulty swallowing'],'A','Dys- (bad) + -pepsia (digestion). Vomiting blood is hematemesis, and difficulty swallowing is dysphagia.',EHR),
  q(DIG,'What is hematemesis?','Vomiting blood',['Blood in the stool','Coughing up blood','Blood in the urine'],'B','Hemat/o (blood) + -emesis (vomiting). Coughing up blood is hemoptysis, and blood in urine is hematuria.',EHR),
  q(DIG,'What is a colonoscopy?','Viewing the large intestine',['Removing the large intestine','Opening the colon to the skin','Repairing the colon wall'],'C','Col/o or colon/o + -scopy (visual examination). An opening to the skin is a colostomy.',EHR),
  q(CV,'What does bradycardia mean?','Slow heart rate',['Fast heart rate','Enlarged heart','Heart inflammation'],'D','Brady- (slow) + cardi/o (heart) + -ia. An adult resting rate below about 60 beats per minute is bradycardia.',EHR),
  q(CV,'What is an arrhythmia?','An irregular heartbeat',['A blocked coronary artery','A weak heart valve','A heart muscle tumor'],'A','A- or an- (without) + rhythm + -ia. Also called dysrhythmia, it is any abnormal heart rhythm.',EHR),
  q(NERV,'What is meningitis?','Inflammation of the brain’s coverings',['Inflammation of the brain tissue','Bleeding inside the skull','A tumor of the spinal cord'],'B','Mening/o refers to the meninges. Brain tissue inflammation is encephalitis.',EHR),
  q(NERV,'What is aphasia?','Loss of the ability to use language',['Loss of the ability to swallow','Loss of feeling in the hands','Loss of balance when walking'],'C','A- (without) + -phasia (speech). It often follows a stroke affecting the brain’s language areas.',EHR),
  q(ENDO,'What does hyperglycemia mean?','High blood sugar',['Low blood sugar','High blood calcium','Low blood sodium'],'D','Hyper- (above) + glyc/o (sugar) + -emia. It is a key sign of diabetes mellitus.',EHR),
  q(ENDO,'Which condition results from long-term excess cortisol?','Cushing syndrome',['Addison disease','Graves disease','Diabetes insipidus'],'A','Cushing syndrome causes a round face, central weight gain and fragile skin; Addison disease is too little cortisol.',EHR),
  q(ENDO,'What is exophthalmos?','Bulging of the eyes',['Drooping of the eyelids','Clouding of the lenses','Crossing of the eyes'],'B','Ex- (out) + ophthalm/o (eye). It is often seen with hyperthyroidism, especially Graves disease.',EHR),
  q(REPRO,'What does dysmenorrhea mean?','Painful menstruation',['Absent menstruation','Heavy menstruation','Irregular menstruation'],'C','Dys- (painful) + men/o (menses) + -rrhea (flow). Absence is amenorrhea, and heavy flow is menorrhagia.',EHR),
  q(REPRO,'What is salpingitis?','Inflamed uterine tube',['Inflamed ovary tissue','Inflamed cervix','Inflamed vagina'],'D','Salping/o refers to the fallopian tube (and the eustachian tube). Ovary is oophor/o, cervix is cervic/o.',EHR),
  q(REPRO,'What is orchitis?','Inflammation of a testis',['Inflammation of the prostate','Inflammation of the urethra','Inflammation of the scrotum skin'],'A','Orch/o, orchi/o and orchid/o refer to the testis. Prostate inflammation is prostatitis.',EHR),
  q(INTEG,'What does erythema mean?','Redness of the skin',['Yellowing of the skin','Thickening of the skin','Peeling of the skin'],'B','Erythr/o means red. Yellowing is jaundice, thickening may be keratosis and peeling is desquamation.',EHR),
  q(INTEG,'What are petechiae?','Tiny red or purple dots',['Large raised wheals','Fluid-filled blisters','Rough, scaly patches'],'C','Petechiae are pinpoint hemorrhages under the skin; larger bruises are ecchymoses.',EHR),
  q(INTEG,'What does dermatitis mean?','Inflammation of the skin',['Disease of the hair','Infection of a nail','Tumor of the skin'],'D','Derm/o or dermat/o (skin) + -itis. Contact dermatitis follows exposure to an irritant or allergen.',EHR),
  q(URIN,'What does anuria mean?','Absence of urine production',['Painful urination','Scanty urine output','Night-time urination'],'A','An- (without) + -uria. Scanty output is oliguria, painful urination is dysuria and night urination is nocturia.',EHR),
  q(URIN,'What is pyelonephritis?','Infection of the kidney',['Infection of the bladder','Stones in the ureter','Narrowing of the urethra'],'B','Pyel/o (renal pelvis) + nephr/o (kidney) + -itis. It often begins as a bladder infection that travels upward.',EHR)
 ],6202)
};
